  --accent-ink: #ffffff;
  --border: #e6e4dd;
  --border-strong: #c9c6bc;
  --focus: #1a1b1f;
  --radius: 14px;
  --shadow-sm: 0 1px 2px rgba(20, 22, 30, 0.04), 0 1px 3px rgba(20, 22, 30, 0.06);
  --shadow-md: 0 4px 12px rgba(20, 22, 30, 0.06), 0 12px 32px rgba(20, 22, 30, 0.08);
  --max: 760px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14141a;
    --surface: #1d1e25;
    --ink: #f3f2ef;
    --ink-muted: #a4a8b3;
    --accent: #a191ff;
    --accent-ink: #14141a;
    --border: #2a2c35;
    --border-strong: #3b3e49;
    --focus: #f3f2ef;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

p {
  margin: 0 0 1em;
}
p:last-child {
  margin-bottom: 0;
}

a {
  color: var(--accent);
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -100px;
  background: var(--ink);
  color: var(--bg);
  padding: 0.6rem 0.9rem;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 600;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

/* Header */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.site-header__inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 0.9rem 1.25rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  font-weight: 700;
  text-decoration: none;
  color: var(--ink);
  font-size: 1.05rem;
}
.brand__mark {
  font-size: 1.4rem;
  line-height: 1;
}
.primary-nav {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 0.25rem;
  flex-wrap: wrap;
}
.primary-nav a {
  display: inline-block;
  padding: 0.5rem 0.85rem;
  border-radius: 999px;
  text-decoration: none;
  color: var(--ink-muted);
  font-weight: 500;
  font-size: 0.95rem;
}
.primary-nav a:hover {
  color: var(--ink);
  background: var(--bg);
}
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  background: var(--bg);
}

/* Layout */
main {
  max-width: var(--max);
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

/* Hero */
.hero {
  text-align: center;
  margin-bottom: 3rem;
}
.eyebrow {
  display: inline-block;
  margin: 0 0 1rem;
  padding: 0.3rem 0.75rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-radius: 999px;
}
.hero h1 {
  margin: 0 0 1rem;
  font-size: clamp(1.85rem, 4.5vw, 2.6rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.lede {
  color: var(--ink-muted);
  font-size: 1.05rem;
  max-width: 38em;
  margin: 0 auto;
}

/* Section heading */
.section-heading {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-muted);
  margin: 0 0 1rem;
  padding-left: 0.25rem;
}

/* FAQ list */
.faq {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.example:hover {
  border-color: var(--border-strong);
}
.example:has(.faq__trigger[aria-expanded="true"]) {
  box-shadow: var(--shadow-md);
  border-color: var(--border-strong);
}

.faq__question {
  margin: 0;
  font-size: inherit;
  font-weight: inherit;
}

.faq__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.15rem 1.25rem;
  background: transparent;
  border: 0;
  border-radius: var(--radius);
  text-align: left;
  font: inherit;
  color: var(--ink);
  font-weight: 600;
  font-size: 1.02rem;
  cursor: pointer;
}
.faq__trigger:hover {
  color: var(--accent);
}
.faq__trigger:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.faq__label {
  flex: 1;
}

/* Plus / minus icon built from CSS so it adapts to forced-colors */
.faq__icon {
  position: relative;
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  opacity: 0.7;
}
.faq__icon::before,
.faq__icon::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  background: currentColor;
  transition: transform 0.2s ease;
}
.faq__icon::before {
  width: 10px;
  height: 1.5px;
  transform: translate(-50%, -50%);
}
.faq__icon::after {
  width: 1.5px;
  height: 10px;
  transform: translate(-50%, -50%);
}
.faq__trigger[aria-expanded="true"] .faq__icon {
  opacity: 1;
}
.faq__trigger[aria-expanded="true"] .faq__icon::after {
  transform: translate(-50%, -50%) scaleY(0);
}

/* Panel */
.details {
  padding: 0 1.25rem 1.25rem;
  color: var(--ink-muted);
}
.details[hidden] {
  display: none;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border);
  background: var(--surface);
  padding: 1.5rem 1.25rem;
  text-align: center;
  color: var(--ink-muted);
  font-size: 0.9rem;
}

/* Forced colors: ensure visible boundaries and focus */
@media (forced-colors: active) {
  .example {
    border: 1px solid CanvasText;
  }
  .faq__trigger:focus-visible {
    outline: 3px solid Highlight;
  }
  .faq__icon {
    border-color: CanvasText;
  }
  .faq__icon::before,
  .faq__icon::after {
    background: CanvasText;
  }
}
