+// Initialize FAQ disclosure widgets.
+// Panels start visible in source HTML so they remain readable without JS
+// (e.g. reader mode). We collapse them here on init.
+(function () {
+  const triggers = document.querySelectorAll('.faq__trigger');
+
+  triggers.forEach((trigger) => {
+    const example = trigger.closest('.example');
+    const panel = example && example.querySelector('.details');
+    if (!panel) return;
+
+    trigger.setAttribute('aria-expanded', 'false');
+    panel.hidden = true;
+
+    trigger.addEventListener('click', () => {
+      const open = trigger.getAttribute('aria-expanded') === 'true';
+      trigger.setAttribute('aria-expanded', String(!open));
+      panel.hidden = open;
+    });
+
+    trigger.addEventListener('keydown', (event) => {
+      if (event.key === 'Escape' && trigger.getAttribute('aria-expanded') === 'true') {
+        trigger.setAttribute('aria-expanded', 'false');
+        panel.hidden = true;
+      }
+    });
+  });
+})();
+
