}
.brand__mark {
  font-size: 1.4rem;
  line-height: 1;
}
.primary-nav {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 0.25rem;
  flex-wrap: wrap;
}
.primary-nav a {
  display: inline-block;
  padding: 0.5rem 0.85rem;
