  color: var(--ink);
  background: var(--bg);
}
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  background: var(--bg);
}

/* Layout */
main {
  max-width: var(--max);
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

/* Hero */
.hero {
  text-align: center;
  margin-bottom: 3rem;
}
.eyebrow {
