  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-radius: 999px;
}
.hero h1 {
  margin: 0 0 1rem;
  font-size: clamp(1.85rem, 4.5vw, 2.6rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.lede {
  color: var(--ink-muted);
  font-size: 1.05rem;
  max-width: 38em;
  margin: 0 auto;
}

/* Section heading */
.section-heading {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-muted);
  margin: 0 0 1rem;
  padding-left: 0.25rem;
}

/* FAQ list */
.faq {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.example:hover {
  border-color: var(--border-strong);
}
.example:has(.faq__trigger[aria-expanded="true"]) {
  box-shadow: var(--shadow-md);
  border-color: var(--border-strong);
}

.faq__question {
  margin: 0;
  font-size: inherit;
  font-weight: inherit;
}

.faq__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.15rem 1.25rem;
  background: transparent;
  border: 0;
  border-radius: var(--radius);
  text-align: left;
  font: inherit;
  color: var(--ink);
  font-weight: 600;
  font-size: 1.02rem;
  cursor: pointer;
}
.faq__trigger:hover {
  color: var(--accent);
}
.faq__trigger:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.faq__label {
  flex: 1;
}

/* Plus / minus icon built from CSS so it adapts to forced-colors */
.faq__icon {
  position: relative;
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  opacity: 0.7;
}
.faq__icon::before,
.faq__icon::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  background: currentColor;
  transition: transform 0.2s ease;
}
.faq__icon::before {
  width: 10px;
  height: 1.5px;
  transform: translate(-50%, -50%);
}
.faq__icon::after {
  width: 1.5px;
  height: 10px;
  transform: translate(-50%, -50%);
}
.faq__trigger[aria-expanded="true"] .faq__icon {
  opacity: 1;
}
.faq__trigger[aria-expanded="true"] .faq__icon::after {
  transform: translate(-50%, -50%) scaleY(0);
}

/* Panel */
.details {
